<?php
session_start();
require '../../config/db.php';
if (!isset($_SESSION['cliente_id'])) { header('Location: ../../auth/login.php'); exit; }
function h($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$cliente_id=(int)$_SESSION['cliente_id'];
$stmt=$pdo->prepare('SELECT * FROM clientes WHERE id=?');$stmt->execute([$cliente_id]);$cliente=$stmt->fetch(PDO::FETCH_ASSOC);
$logo=!empty($cliente['logo'])?'../../uploads/clientes/logos/'.basename($cliente['logo']):'';
$stmt=$pdo->prepare('SELECT * FROM eventos WHERE cliente_id=? ORDER BY data_inicio ASC LIMIT 60');$stmt->execute([$cliente_id]);$eventos=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT protocolo,titulo,descricao,status,prazo FROM solicitacoes WHERE cliente_id=? AND prazo IS NOT NULL ORDER BY prazo ASC LIMIT 20");$stmt->execute([$cliente_id]);$prazos=$stmt->fetchAll(PDO::FETCH_ASSOC);
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Calendário - Infoservice</title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-client-logo-box"><?php if($logo): ?><img src="<?= h($logo) ?>" alt="Logo do cliente"><?php else: ?>📅<?php endif; ?></div><div><h1>Calendário de atendimentos</h1><p>Agenda de visitas, serviços e prazos estimados dos chamados.</p></div></div><div class="hd-user"><span class="hd-chip"><?= h($cliente['nome']??'Cliente') ?></span><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="../../auth/logout.php">Sair</a></div></div></header><main class="hd-main"><div class="hd-container"><div class="hd-grid"><section class="hd-card hd-card-pad"><div class="hd-section-head"><div><h2>Agenda</h2><p>Compromissos cadastrados pela Infoservice.</p></div><a class="hd-btn hd-btn-primary" href="mensagens.php">💬 Solicitar agendamento</a></div><div class="hd-calendar-list"><?php if(!$eventos): ?><div class="hd-empty">🗓️<strong>Nenhum evento agendado</strong>Quando uma visita ou manutenção for marcada, ela aparecerá aqui.</div><?php endif; ?><?php foreach($eventos as $e): ?><article class="hd-event"><strong><?= h($e['titulo']) ?></strong><div class="hd-ticket-meta">Início: <?= date('d/m/Y H:i', strtotime($e['data_inicio'])) ?> • Fim: <?= date('d/m/Y H:i', strtotime($e['data_fim'])) ?></div></article><?php endforeach; ?></div></section><aside class="hd-sidebar"><section class="hd-card hd-card-pad"><div class="hd-section-head"><h3>Prazos dos chamados</h3></div><div class="hd-sidebar-list"><?php if(!$prazos): ?><div class="hd-mini"><strong>Sem prazos ativos</strong><p>Abra um chamado para gerar prazo estimado conforme a prioridade.</p></div><?php endif; ?><?php foreach($prazos as $p): ?><div class="hd-mini"><strong><?= h($p['protocolo'] ?: 'Chamado') ?></strong><p><?= h($p['titulo'] ?: mb_substr($p['descricao'],0,60)) ?></p><small class="hd-ticket-meta">Prazo: <?= date('d/m/Y H:i', strtotime($p['prazo'])) ?> • <?= h(ucfirst($p['status'])) ?></small></div><?php endforeach; ?></div></section><section class="hd-card hd-card-pad" style="margin-top:16px"><div class="hd-sidebar-list"><a class="hd-btn hd-btn-outline" href="mensagens.php">💬 Mensagens</a><a class="hd-btn hd-btn-outline" href="financeiro.php">💰 Financeiro</a><a class="hd-btn hd-btn-primary" href="solicitar.php">➕ Abrir chamado</a></div></section></aside></div></div></main></div><script>window.HD_CHAT_CONFIG={endpointBase:'../../controllers/',chatUrl:'mensagens.php'};</script><script src="../../assets/js/live-chat-alerts.js"></script></body></html>